"""Prefix Trie with insertion and node pruning deletion."""

from typing import List, Optional
from trie_node import TrieNode


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        curr = self.root
        for ch in word:
            if ch not in curr.children:
                curr.children[ch] = TrieNode()
            curr = curr.children[ch]
        curr.is_terminal = True

    def search(self, word: str) -> bool:
        curr = self.root
        for ch in word:
            if ch not in curr.children:
                return False
            curr = curr.children[ch]
        return curr.is_terminal

    def delete(self, word: str) -> bool:
        # BUG: Only unsets is_terminal flag at the leaf without recursive dead-branch child pruning
        curr = self.root
        for ch in word:
            if ch not in curr.children:
                return False
            curr = curr.children[ch]
        if not curr.is_terminal:
            return False
        curr.is_terminal = False
        return True

    def has_prefix(self, prefix: str) -> bool:
        curr = self.root
        for ch in prefix:
            if ch not in curr.children:
                return False
            curr = curr.children[ch]
        return True

