"""Autocomplete search index."""

from typing import List
from trie import PrefixTrie


class AutocompleteIndex:
    def __init__(self):
        self.trie = PrefixTrie()

    def add_keyword(self, kw: str) -> None:
        self.trie.insert(kw)

    def remove_keyword(self, kw: str) -> bool:
        return self.trie.delete(kw)

    def suggest_prefix_exists(self, prefix: str) -> bool:
        return self.trie.has_prefix(prefix)

