"""Prefix Trie with insertion and node pruning deletion."""

from typing import List, Optional
from trie_node import TrieNode


class PrefixTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        curr = self.root
        for ch in word:
            if ch not in curr.children:
                curr.children[ch] = TrieNode()
            curr = curr.children[ch]
        curr.is_terminal = True

    def search(self, word: str) -> bool:
        curr = self.root
        for ch in word:
            if ch not in curr.children:
                return False
            curr = curr.children[ch]
        return curr.is_terminal

    def delete(self, word: str) -> bool:
        def _delete_helper(node: TrieNode, idx: int) -> bool:
            if idx == len(word):
                if not node.is_terminal:
                    return False
                node.is_terminal = False
                return len(node.children) == 0

            ch = word[idx]
            if ch not in node.children:
                return False
            should_delete_child = _delete_helper(node.children[ch], idx + 1)
            if should_delete_child:
                del node.children[ch]
                return len(node.children) == 0 and not node.is_terminal
            return False

        if not self.search(word):
            return False
        _delete_helper(self.root, 0)
        return True

    def has_prefix(self, prefix: str) -> bool:
        curr = self.root
        for ch in prefix:
            if ch not in curr.children:
                return False
            curr = curr.children[ch]
        return True
